from solution import adjacent_num_product


def test_issue_example_list():
    """Largest product of the pair of adjacent elements for [1,2,3,4,5,6] is 30."""
    assert adjacent_num_product([1, 2, 3, 4, 5, 6]) == 30  # 5*6=30


def test_issue_two_elements():
    """Largest product of the pair of adjacent elements with only one pair [3,7] is 21."""
    assert adjacent_num_product([3, 7]) == 21  # 3*7=21


def test_issue_all_negatives():
    """Largest product of the pair of adjacent elements for all negatives is from two negatives."""
    assert adjacent_num_product([-5, -4, -3, -2]) == 20  # (-5)*(-4)=20


def test_issue_mixed_signs():
    """Largest product of the pair of adjacent elements with mixed signs and zero is 5."""
    assert adjacent_num_product([-5, -1, 0, 2, -3]) == 5  # (-5)*(-1)=5


def test_issue_all_zeros():
    """Largest product of the pair of adjacent elements for [0,0,0] is 0."""
    assert adjacent_num_product([0, 0, 0]) == 0  # 0*0=0


def test_issue_all_products_negative():
    """Largest product of the pair of adjacent elements can be negative when all pairs are negative."""
    assert adjacent_num_product([2, -3, 4, -5]) == -6  # 2*(-3)=-6


def test_issue_max_in_middle():
    """Largest product of the pair of adjacent elements can be in the middle of the list."""
    assert adjacent_num_product([1, 5, 2, 1]) == 10  # 5*2=10


def test_issue_descending_order():
    """Largest product of the pair of adjacent elements for descending [6,5,4,3,2,1] is 30."""
    assert adjacent_num_product([6, 5, 4, 3, 2, 1]) == 30  # 6*5=30


def test_contract_adjacent_only():
    """Contract: largest product of the pair of adjacent elements ignores non-adjacent pairs."""
    assert adjacent_num_product([10, 1, 1, 10]) == 10  # 10*1=10, non-adjacent 10*10=100 ignored


def test_contract_product_not_sum():
    """Contract: largest product of the pair of adjacent elements is a product, not a sum."""
    assert adjacent_num_product([4, 5, 1]) == 20  # 4*5=20, sum would be 4+5=9
